using System;
using System.Collections.Generic;
using System.Web;
using TplCore.Element;
using System.Data;
using System.Text;

/// <summary>
/// Generate Refresh League
/// </summary>
namespace Fanex.Age.UI.Components
{
    public class RefreshLeague
    {
        public string RenderLeagueList(DataTable leagues, int _leagueId)
        {
            StringBuilder sb = new StringBuilder();
            if (leagues != null && leagues.Rows.Count > 0)
            {
                DataRowCollection Rows = leagues.Rows;
                foreach (DataRow dr in Rows)
                {
                    int leagueId = Convert.ToInt32(dr["leagueid"]);
                    if (leagueId == _leagueId)
                    {
                        sb.Append(String.Format("<option value='{0}' selected>{1}</option>", leagueId, dr["leaguename"].ToString()));
                    }
                    else
                    {
                        sb.Append(String.Format("<option value='{0}'>{1}</option>", leagueId, dr["leaguename"].ToString()));
                    }
                }
            }
            return "<select id='ddlLeague' name='ddlLeague' onchange='ChangeLeague()'>" + sb.ToString() + "</select>";
        }
    }
}